package dustin.cex.domains.bitcoin;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import dustin.cex.shared.http.EngineDepositClient;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.core.env.MapPropertySource;

/** 직접 소유한 실행기에서 배수/대기/종료를 확인한다. DB·노드·엔진·브로커는 만들지 않는다. */
class BitcoinCreditWorkerTest {
    BitcoinSettings configured(){return new BitcoinSettings("http://127.0.0.1:1","reader","x".repeat(32),"cex_watch","REGTEST");}
    BitcoinCreditWorker worker(BitcoinCreditProcessing processing,Duration idle){return new BitcoinCreditWorker(configured(),processing,true,idle,80,320);}
    Optional<BitcoinCreditProcessing.Report> result(EngineDepositClient.Outcome outcome){return Optional.of(new BitcoinCreditProcessing.Report(UUID.randomUUID(),"RETRY","LOCAL_TEST",outcome));}
    @Test void disabledWorkerDoesNotAllocateOrCall(){var processing=mock(BitcoinCreditProcessing.class);var worker=new BitcoinCreditWorker(configured(),processing,false);try{worker.start();assertNull(org.springframework.test.util.ReflectionTestUtils.getField(worker,"scheduler"));verifyNoInteractions(processing);}finally{worker.stop();}}
    @Test void missingNodeConfigurationDoesNotStartTheWorker(){var processing=mock(BitcoinCreditProcessing.class);var settings=new BitcoinSettings("","","","","REGTEST");var worker=new BitcoinCreditWorker(settings,processing,true);try{worker.start();assertNull(org.springframework.test.util.ReflectionTestUtils.getField(worker,"scheduler"));verifyNoInteractions(processing);}finally{worker.stop();}}
    @Test void testProfileExcludesAutomaticExecutionEvenWhenEnabled(){var processing=mock(BitcoinCreditProcessing.class);try(var context=new AnnotationConfigApplicationContext()){context.getEnvironment().setActiveProfiles("test");context.getEnvironment().getPropertySources().addFirst(new MapPropertySource("owned-test",Map.of("bitcoin.processing.enabled","true")));context.registerBean(BitcoinSettings.class,this::configured);context.registerBean(BitcoinCreditProcessing.class,()->processing);context.registerBean("bitcoinCreditSchemaInitializer",Object.class,Object::new);context.register(BitcoinCreditWorker.class);context.refresh();assertFalse(context.containsBean("bitcoinCreditWorker"));verifyNoInteractions(processing);}}
    @Test void readyItemsAreDrainedWithoutWaitingBetweenThem()throws Exception{var processing=mock(BitcoinCreditProcessing.class);var third=new CountDownLatch(1);var calls=new AtomicInteger();when(processing.processNext()).thenAnswer(call->{int n=calls.incrementAndGet();if(n==3)third.countDown();return n<=3?result(EngineDepositClient.Outcome.DURABLY_CREDITED):Optional.empty();});var worker=worker(processing,Duration.ofSeconds(5));try{worker.start();assertTrue(third.await(2,TimeUnit.SECONDS));}finally{worker.stop();}assertTrue(calls.get()>=3);}
    @Test void repeatedStartUsesOneLongLivedExecutionThread()throws Exception{var processing=mock(BitcoinCreditProcessing.class);var called=new CountDownLatch(3);var threads=ConcurrentHashMap.<Long>newKeySet();when(processing.processNext()).thenAnswer(call->{threads.add(Thread.currentThread().threadId());called.countDown();return Optional.empty();});var worker=worker(processing,Duration.ofMillis(15));try{worker.start();worker.start();assertTrue(called.await(2,TimeUnit.SECONDS));}finally{worker.stop();}assertEquals(1,threads.size());}
    @Test void slowProcessingDoesNotAccumulateOverlappingCalls()throws Exception{var processing=mock(BitcoinCreditProcessing.class);var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var calls=new AtomicInteger();var active=new AtomicInteger();var maximum=new AtomicInteger();when(processing.processNext()).thenAnswer(call->{calls.incrementAndGet();maximum.accumulateAndGet(active.incrementAndGet(),Math::max);try{entered.countDown();assertTrue(release.await(2,TimeUnit.SECONDS));return Optional.empty();}finally{active.decrementAndGet();}});var worker=worker(processing,Duration.ofMillis(10));try{worker.start();assertTrue(entered.await(2,TimeUnit.SECONDS));Thread.sleep(60);assertEquals(1,calls.get());}finally{release.countDown();worker.stop();}assertEquals(1,maximum.get());}
    @Test void runtimeFailureWaitsBeforeResumingTheSameWorker()throws Exception{var processing=mock(BitcoinCreditProcessing.class);var second=new CountDownLatch(1);var calls=new AtomicInteger();var firstAt=new AtomicLong();var secondAt=new AtomicLong();when(processing.processNext()).thenAnswer(call->{if(calls.incrementAndGet()==1){firstAt.set(System.nanoTime());throw new IllegalStateException("격리 처리 장애");}secondAt.compareAndSet(0,System.nanoTime());second.countDown();return Optional.empty();});var worker=worker(processing,Duration.ofMillis(10));try{worker.start();assertTrue(second.await(2,TimeUnit.SECONDS));}finally{worker.stop();}assertTrue(secondAt.get()-firstAt.get()>=Duration.ofMillis(80).toNanos());}
    @Test void consecutiveEngineUnknownOutcomesIncreaseTheGlobalWait()throws Exception{var processing=mock(BitcoinCreditProcessing.class);var third=new CountDownLatch(1);var times=new CopyOnWriteArrayList<Long>();when(processing.processNext()).thenAnswer(call->{times.add(System.nanoTime());if(times.size()==3)third.countDown();return result(EngineDepositClient.Outcome.OUTCOME_UNKNOWN);});var worker=worker(processing,Duration.ofMillis(10));try{worker.start();assertTrue(third.await(3,TimeUnit.SECONDS));}finally{worker.stop();}assertTrue(times.get(1)-times.get(0)>=Duration.ofMillis(80).toNanos());assertTrue(times.get(2)-times.get(1)>=Duration.ofMillis(160).toNanos());}
    @Test void shutdownStopsBeforeTheNextReadyItem()throws Exception{var processing=mock(BitcoinCreditProcessing.class);var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var calls=new AtomicInteger();when(processing.processNext()).thenAnswer(call->{calls.incrementAndGet();entered.countDown();try{release.await(2,TimeUnit.SECONDS);}catch(InterruptedException stopped){Thread.currentThread().interrupt();}return result(EngineDepositClient.Outcome.DURABLY_CREDITED);});var worker=worker(processing,Duration.ofMillis(10));try(var pool=Executors.newSingleThreadExecutor()){worker.start();assertTrue(entered.await(2,TimeUnit.SECONDS));var stopped=pool.submit(worker::stop);long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(1);while(Boolean.TRUE.equals(org.springframework.test.util.ReflectionTestUtils.getField(worker,"active"))&&System.nanoTime()<deadline)Thread.sleep(5);assertFalse((Boolean)org.springframework.test.util.ReflectionTestUtils.getField(worker,"active"));release.countDown();stopped.get(2,TimeUnit.SECONDS);}finally{release.countDown();worker.stop();}assertEquals(1,calls.get());}
}
